from pipeline.steps import Squeeze, Strip, Truncate, Upper

STEPS = {"upper": Upper(), "strip": Strip(), "squeeze": Squeeze()}
ARG_STEPS = {"truncate": Truncate}


def lookup(name: str):
    if ":" in name:
        base, arg = name.split(":", 1)
        if not base:
            raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(STEPS))}")
        if base not in STEPS:
            raise KeyError(f"no step named {base!r}. Known: {', '.join(sorted(STEPS))}")
        step = STEPS[base]
        original_apply = step.apply

        def apply(text: str) -> str:
            return original_apply(text, arg)

        step.apply = apply
        return step
    if name not in STEPS:
        if name in ARG_STEPS:
            # A bare name for an argument-only step: the user forgot the colon+arg
            step = ARG_STEPS[name]()
            return step
        raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(STEPS))}")
    return STEPS[name]

